--UNCOMMENT SET SQLBLANKLINES ON TO RUN THIS SCRIPT IN SQLPLUS

--SET SQLBLANKLINES ON

DROP VIEW PS_EO_CHUNKALT_VW
/
CREATE VIEW PS_EO_CHUNKALT_VW (RECNAME, RECDESCR) AS SELECT RECNAME 
,RECDESCR FROM PSRECDEFN WHERE RTRIM(SUBSTR(RECNAME, 1, 15)) LIKE
 '%_EOV'
/